class Solution:
    def maximumSetSize(self, nums1, nums2):
        s1, s2 = set(nums1), set(nums2)
        common = s1 & s2
        half = len(nums1) // 2
        k1 = min(len(s1 - common), half)
        k2 = min(len(s2 - common), half)
        return k1 + k2 + min(len(common), 2 * half - k1 - k2)

