        def keep(nums, other):
            other_set = set(other)
            uniq = [x for x in dict.fromkeys(nums) if x not in other_set]
            rest = [x for x in dict.fromkeys(nums) if x in other_set]
            chosen = uniq[:len(nums) // 2]
            chosen += rest[:len(nums) // 2 - len(chosen)]
            while len(chosen) < len(nums) // 2:
                chosen.append(nums[0])
            return set(chosen)
        return len(keep(nums1, nums2) | keep(nums2, nums1))

