class Solution {
public:
    int maximumSetSize(vector<int>& nums1, vector<int>& nums2) {
        auto keep = [](vector<int>& nums, vector<int>& other) {
            unordered_set<int> os(other.begin(), other.end());
            unordered_set<int> seen;
            vector<int> uniq, rest;
            for (int x : nums) if (seen.insert(x).second) {
                if (os.count(x)) rest.push_back(x); else uniq.push_back(x);
            }
            int half = nums.size() / 2;
            unordered_set<int> res;
            for (int i = 0; i < half && i < (int)uniq.size(); i++) res.insert(uniq[i]);
            for (int i = 0; res.size() < (size_t)half && i < (int)rest.size(); i++) res.insert(rest[i]);
            while (res.size() < (size_t)half) res.insert(nums[res.size()]);
            return res;
        };
        auto a = keep(nums1, nums2), b = keep(nums2, nums1);
        int sz = a.size();
        for (int x : b) a.insert(x);
        return max(sz, (int)a.size());
    }
};

