class Solution {
    public int maximumSetSize(int[] nums1, int[] nums2) {
        Set<Integer> a = keep(nums1, nums2), b = keep(nums2, nums1);
        a.addAll(b);
        return a.size();
    }
    private Set<Integer> keep(int[] nums, int[] other) {
        Set<Integer> os = new HashSet<>(), seen = new HashSet<>(), res = new HashSet<>();
        for (int x : other) os.add(x);
        List<Integer> uniq = new ArrayList<>(), rest = new ArrayList<>();
        for (int x : nums) if (seen.add(x)) {
            if (os.contains(x)) rest.add(x); else uniq.add(x);
        }
        int half = nums.length / 2;
        for (int i = 0; i < half && i < uniq.size(); i++) res.add(uniq.get(i));
        for (int i = 0; res.size() < half && i < rest.size(); i++) res.add(rest.get(i));
        int filler = 0;
        while (res.size() < half) res.add(nums[filler++]);
        return res;
    }
}

