var maximumSetSize = function(nums1, nums2) {
    function keep(nums, other) {
        const os = new Set(other), seen = new Set(), res = new Set();
        const uniq = [], rest = [];
        for (const x of nums) if (!seen.has(x)) {
            seen.add(x);
            (os.has(x) ? rest : uniq).push(x);
        }
        const half = nums.length / 2;
        for (let i = 0; i < half && i < uniq.length; i++) res.add(uniq[i]);
        for (let i = 0; res.size < half && i < rest.length; i++) res.add(rest[i]);
        let f = 0;
        while (res.size < half) res.add(nums[f++]);
        return res;
    }
    const a = keep(nums1, nums2), b = keep(nums2, nums1);
    for (const x of b) a.add(x);
    return a.size;
};
